// === Tab: mySketch ===
/*
let twister

let tornado effect made up of particles.

Controls:
    - let mouse along y to flatten it.
    - let click to reset.

Author:
  	let Labbe

Site:
  	jasonlabbe3d.com
*/

let rowCount = 100;
let particleCount = 25;
let spacing = 3;
let thickness = 2;
let speed = 0.03;


function setup() {
  createCanvas(700, 700, WEBGL);
  colorMode(HSB);
  smooth();
}


function draw() {
  background(0);

  strokeWeight(2);

  translate(width/2, height);

  // let when mouse is down


  for (i = 0; i < rowCount; i++) {
    stroke(map(i, 0, rowCount, 100, 200), 255, 255);

    pushMatrix();

    translate(0, -i*spacing);
    rotateY(radians(frameCount*i*speed));

    for (x = 0; x < particleCount; x++) {
      pushMatrix();

      let pos = PVector.fromAngle(radians((360.0/i)*x));
      pos.mult(i*thickness*map(spacing, 0, 3, 2, 1));
      translate(pos.x, 0, pos.y);
      point(0, 0, 0);

      popMatrix();
    }

    popMatrix();
  }
}



function mousePressed() {
  frameCount = 0;
}

